import React from "react";
import Link from "next/link";
import {
  ImageDown,
  Maximize2,
  FileImage,
  Crop,
  Smartphone,
  Zap,
  RotateCw,
  Sparkles,
  SplitSquareVertical,
  Layers,
  FileText,
  FileDown,
  FilePlus,
  Scissors,
  Code2,
  Binary,
  SearchCode,
  Type,
  FileCode,
  Percent,
  Ratio,
  QrCode,
  ArrowRight,
  HelpCircle,
  LucideIcon,
} from "lucide-react";
import { Tool } from "@/data/tools";
import { Badge } from "../ui/Badge";

// Icon mapping dictionary
const ICON_MAP: Record<string, LucideIcon> = {
  ImageDown,
  Maximize2,
  FileImage,
  Crop,
  Smartphone,
  Zap,
  RotateCw,
  Sparkles,
  SplitSquareVertical,
  Layers,
  FileText,
  FileDown,
  FilePlus,
  Scissors,
  Code2,
  Binary,
  SearchCode,
  Type,
  FileCode,
  Percent,
  Ratio,
  QrCode,
};

// Category icon color & gradient presets
const CATEGORY_STYLES: Record<string, { bg: string; color: string }> = {
  images: { bg: "bg-blue-50 text-blue-600 border-blue-100", color: "#4F8CFF" },
  pdf: { bg: "bg-rose-50 text-rose-600 border-rose-100", color: "#F43F5E" },
  developer: { bg: "bg-purple-50 text-purple-600 border-purple-100", color: "#8B5CF6" },
  text: { bg: "bg-amber-50 text-amber-600 border-amber-100", color: "#F59E0B" },
  calculators: { bg: "bg-emerald-50 text-emerald-600 border-emerald-100", color: "#10B981" },
  social: { bg: "bg-indigo-50 text-indigo-600 border-indigo-100", color: "#6366F1" },
  more: { bg: "bg-slate-50 text-slate-600 border-slate-200", color: "#64748B" },
};

interface ToolCardProps {
  tool: Tool;
  className?: string;
}

export function ToolCard({ tool, className = "" }: ToolCardProps) {
  const IconComponent = ICON_MAP[tool.iconName] || HelpCircle;
  const categoryStyle = CATEGORY_STYLES[tool.category] || {
    bg: "bg-indigo-50 text-indigo-600 border-indigo-100",
    color: "#6657FF",
  };

  return (
    <Link
      href={`/tools/${tool.slug}`}
      className={`group relative flex flex-col justify-between p-6 bg-white rounded-2xl md:rounded-3xl border border-slate-200/80 shadow-sm hover:shadow-xl hover:shadow-indigo-500/10 hover:border-indigo-300 transition-all duration-300 hover:-translate-y-1 focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 ${className}`}
    >
      <div>
        {/* Top bar: Icon and optional Popular badge */}
        <div className="flex items-start justify-between mb-4">
          <div
            className={`w-12 h-12 rounded-2xl flex items-center justify-center border transition-transform duration-300 group-hover:scale-105 ${categoryStyle.bg}`}
          >
            <IconComponent className="w-6 h-6" />
          </div>

          {tool.popular && (
            <Badge variant="popular" size="sm">
              Popular
            </Badge>
          )}
        </div>

        {/* Title */}
        <h3 className="text-base font-bold text-[#111936] group-hover:text-indigo-600 transition-colors duration-200 mb-1.5">
          {tool.name}
        </h3>

        {/* Description */}
        <p className="text-xs sm:text-sm text-[#52607A] leading-relaxed line-clamp-2">
          {tool.description}
        </p>
      </div>

      {/* Card bottom: status & arrow button */}
      <div className="mt-5 pt-3 border-t border-slate-100 flex items-center justify-between">
        <span className="text-[11px] font-medium text-slate-400">
          {tool.status === "coming-soon" ? "Coming soon" : "Available"}
        </span>
        <div className="w-8 h-8 rounded-full bg-slate-100 text-slate-600 group-hover:bg-indigo-600 group-hover:text-white flex items-center justify-center transition-all duration-200">
          <ArrowRight className="w-3.5 h-3.5 transform group-hover:translate-x-0.5 transition-transform" />
        </div>
      </div>
    </Link>
  );
}

export default ToolCard;
