"use client";

import React, { useState, useMemo } from "react";
import { Search, Sparkles } from "lucide-react";
import { Tool } from "@/data/tools";
import { CATEGORIES } from "@/data/categories";
import { ToolCard } from "./ToolCard";

interface AllToolsClientProps {
  initialTools: Tool[];
  initialQuery?: string;
}

export function AllToolsClient({ initialTools, initialQuery = "" }: AllToolsClientProps) {
  const [search, setSearch] = useState(initialQuery);
  const [selectedCategory, setSelectedCategory] = useState("all");

  const filteredTools = useMemo(() => {
    return initialTools.filter((tool) => {
      // Category filter
      if (selectedCategory !== "all" && tool.category.toLowerCase() !== selectedCategory.toLowerCase()) {
        return false;
      }
      // Text search
      if (search.trim()) {
        const q = search.trim().toLowerCase();
        return (
          tool.name.toLowerCase().includes(q) ||
          tool.description.toLowerCase().includes(q) ||
          tool.tags.some((t) => t.toLowerCase().includes(q))
        );
      }
      return true;
    });
  }, [initialTools, search, selectedCategory]);

  return (
    <div className="w-full bg-[#F7F8FC] min-h-[70vh] pb-24">
      {/* Search and Category Filter Toolbar */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-8 relative z-20">
        <div className="bg-white rounded-3xl p-5 sm:p-6 shadow-xl border border-slate-200/80 mb-10">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 items-center">
            {/* Search Input */}
            <div className="lg:col-span-6">
              <div className="relative">
                <Search className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                  type="text"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="Search tools by name, action or format (e.g. compress, json, pdf)..."
                  className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm text-[#111936] placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all"
                />
              </div>
            </div>

            {/* Category Selector Tabs */}
            <div className="lg:col-span-6 flex items-center gap-1.5 overflow-x-auto pb-1 scrollbar-none">
              <button
                onClick={() => setSelectedCategory("all")}
                className={`shrink-0 px-3.5 py-2 rounded-xl text-xs font-semibold transition-all ${
                  selectedCategory === "all"
                    ? "bg-indigo-600 text-white shadow-sm"
                    : "bg-slate-100 text-slate-600 hover:bg-slate-200"
                }`}
              >
                All ({initialTools.length})
              </button>
              {CATEGORIES.filter((c) => c.id !== "more").map((cat) => {
                const count = initialTools.filter((t) => t.category === cat.slug).length;
                return (
                  <button
                    key={cat.id}
                    onClick={() => setSelectedCategory(cat.slug)}
                    className={`shrink-0 px-3 py-2 rounded-xl text-xs font-semibold transition-all ${
                      selectedCategory === cat.slug
                        ? "bg-indigo-600 text-white shadow-sm"
                        : "bg-slate-100 text-slate-600 hover:bg-slate-200"
                    }`}
                  >
                    {cat.shortName} ({count})
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        {/* Results Bar */}
        <div className="flex items-center justify-between mb-6 px-1">
          <p className="text-sm text-slate-500 font-medium">
            Showing <strong className="text-[#111936]">{filteredTools.length}</strong> {filteredTools.length === 1 ? "tool" : "tools"}
            {selectedCategory !== "all" && ` in ${selectedCategory}`}
            {search && ` matching "${search}"`}
          </p>

          {(search || selectedCategory !== "all") && (
            <button
              onClick={() => {
                setSearch("");
                setSelectedCategory("all");
              }}
              className="text-xs font-semibold text-indigo-600 hover:text-indigo-700 underline"
            >
              Reset filters
            </button>
          )}
        </div>

        {/* Tools Grid */}
        {filteredTools.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-6">
            {filteredTools.map((tool) => (
              <ToolCard key={tool.slug} tool={tool} />
            ))}
          </div>
        ) : (
          <div className="w-full py-20 px-4 text-center bg-white rounded-3xl border border-slate-200 shadow-sm">
            <div className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center mx-auto mb-4">
              <Sparkles className="w-7 h-7" />
            </div>
            <h3 className="text-lg font-bold text-[#111936] mb-1">
              No tools found
            </h3>
            <p className="text-sm text-slate-500 max-w-sm mx-auto mb-6">
              We couldn&apos;t find any tools matching your search. Try another keyword or browse another category.
            </p>
            <button
              onClick={() => {
                setSearch("");
                setSelectedCategory("all");
              }}
              className="px-5 py-2.5 rounded-xl bg-indigo-600 text-white text-xs font-semibold hover:bg-indigo-700 transition-colors"
            >
              Show all tools
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default AllToolsClient;
